/**
 * Payment references are generated by the system for every method (owner
 * instruction 2026-11-20): PAY-YYYYMMDD-NNNN, unique per business date. The
 * invoice / receipt number of the issued document is kept separately.
 */
export function nextPaymentReference(
  existing: ReadonlyArray<{ referenceNo?: string | null }>,
  paidDate: string,
  isReserved: (reference: string) => boolean = () => false,
): string {
  const prefix = `PAY-${paidDate.replaceAll("-", "")}`;
  const used = new Set(existing.map((item) => item.referenceNo).filter((value): value is string => Boolean(value)));
  let sequence = 1;
  while (true) {
    const candidate = `${prefix}-${String(sequence).padStart(4, "0")}`;
    if (!used.has(candidate) && !isReserved(candidate)) return candidate;
    sequence += 1;
  }
}
